import sys

file_path = '/linux/drivers/net/tun.c'
with open(file_path, 'r') as f:
    content = f.read()

old_block = """\tif (xdp_prog) {
\t\tstruct xdp_buff xdp;
\t\tu32 act;

\t\txdp_init_buff(&xdp, buflen, &tfile->xdp_rxq);
\t\txdp_prepare_buff(&xdp, buf, pad, len, false);

\t\tact = bpf_prog_run_xdp(xdp_prog, &xdp);
\t\tif (act == XDP_REDIRECT || act == XDP_TX) {
\t\t\tget_page(alloc_frag->page);
\t\t\talloc_frag->offset += buflen;
\t\t}
\t\terr = tun_xdp_act(tun, xdp_prog, &xdp, act);
\t\tif (err < 0) {
\t\t\tif (act == XDP_REDIRECT || act == XDP_TX)
\t\t\t\tput_page(alloc_frag->page);
\t\t\tgoto out;
\t\t}

\t\tif (err == XDP_REDIRECT)
\t\t\txdp_do_flush();
\t\tif (err != XDP_PASS)
\t\t\tgoto out;

\t\tpad = xdp.data - xdp.data_hard_start;
\t\tlen = xdp.data_end - xdp.data;
\t}"""

new_block = """\tif (xdp_prog) {
\t\tstruct xdp_buff xdp;
\t\tstruct bpf_net_context __bpf_net_ctx, *bpf_net_ctx;
\t\tu32 act;

\t\txdp_init_buff(&xdp, buflen, &tfile->xdp_rxq);
\t\txdp_prepare_buff(&xdp, buf, pad, len, false);

\t\tbpf_net_ctx = bpf_net_ctx_set(&__bpf_net_ctx);
\t\tact = bpf_prog_run_xdp(xdp_prog, &xdp);
\t\tif (act == XDP_REDIRECT || act == XDP_TX) {
\t\t\tget_page(alloc_frag->page);
\t\t\talloc_frag->offset += buflen;
\t\t}
\t\terr = tun_xdp_act(tun, xdp_prog, &xdp, act);
\t\tif (err < 0) {
\t\t\tif (act == XDP_REDIRECT || act == XDP_TX)
\t\t\t\tput_page(alloc_frag->page);
\t\t\tbpf_net_ctx_clear(bpf_net_ctx);
\t\t\tgoto out;
\t\t}

\t\tif (err == XDP_REDIRECT)
\t\t\txdp_do_flush();
\t\tif (err != XDP_PASS) {
\t\t\tbpf_net_ctx_clear(bpf_net_ctx);
\t\t\tgoto out;
\t\t}

\t\tbpf_net_ctx_clear(bpf_net_ctx);
\t\tpad = xdp.data - xdp.data_hard_start;
\t\tlen = xdp.data_end - xdp.data;
\t}"""

if old_block in content:
    new_content = content.replace(old_block, new_block)
    with open(file_path, 'w') as f:
        f.write(new_content)
    print("Successfully patched")
else:
    print("Could not find block to replace")
    # debug print a subsequence to see where it fails
    sub = old_block[:50]
    if sub in content:
        print("Start found")
    else:
        print("Start NOT found")

import sys

file_path = '/linux/drivers/net/tun.c'
with open(file_path, 'r') as f:
    content = f.read()

old_block = """\tif (skb_xdp) {
\t\tstruct bpf_prog *xdp_prog;
\t\tint ret;

\t\tlocal_bh_disable();
\t\trcu_read_lock();
\t\txdp_prog = rcu_dereference(tun->xdp_prog);
\t\tif (xdp_prog) {
\t\t\tret = do_xdp_generic(xdp_prog, &skb);
\t\t\tif (ret != XDP_PASS) {
\t\t\t\trcu_read_unlock();
\t\t\t\tlocal_bh_enable();
\t\t\t\tgoto unlock_frags;
\t\t\t}
\t\t}
\t\trcu_read_unlock();
\t\tlocal_bh_enable();
\t}"""

new_block = """\tif (skb_xdp) {
\t\tstruct bpf_prog *xdp_prog;
\t\tstruct bpf_net_context __bpf_net_ctx, *bpf_net_ctx;
\t\tint ret;

\t\tlocal_bh_disable();
\t\trcu_read_lock();
\t\txdp_prog = rcu_dereference(tun->xdp_prog);
\t\tif (xdp_prog) {
\t\t\tbpf_net_ctx = bpf_net_ctx_set(&__bpf_net_ctx);
\t\t\tret = do_xdp_generic(xdp_prog, &skb);
\t\t\tbpf_net_ctx_clear(bpf_net_ctx);
\t\t\tif (ret != XDP_PASS) {
\t\t\t\trcu_read_unlock();
\t\t\t\tlocal_bh_enable();
\t\t\t\tgoto unlock_frags;
\t\t\t}
\t\t}
\t\trcu_read_unlock();
\t\tlocal_bh_enable();
\t}"""

if old_block in content:
    new_content = content.replace(old_block, new_block)
    # Check if we should only replace one occurrence? 
    # Tun uses skb_xdp check only in tun_get_user presumably. 
    # I should check if there are multiple occurrences.
    count = content.count(old_block)
    if count > 1:
        print(f"Warning: Found {count} occurrences, replacing all")

    with open(file_path, 'w') as f:
        f.write(new_content)
    print("Successfully patched second location")
else:
    print("Could not find second block to replace")
    sub = old_block[:50]
    if sub in content:
        print("Start found")
    else:
        print("Start NOT found")

